import{_ as t,a as o,c as n,ac as a}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第四册：流利英语 · 单元 1 语法总结","description":"L1–L8 规则、例句、易错点。","frontmatter":{"title":"第四册：流利英语 · 单元 1 语法总结","description":"L1–L8 规则、例句、易错点。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","summary":"L1–L8 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 1：从观察到判断","link":"/life/english/new-concept/book-4/unit-01/overview"},"next":{"text":"第四册：流利英语 · 单元 1 单词与短语","link":"/life/english/new-concept/book-4/unit-01/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 1：从观察到判断","link":"/life/english/new-concept/book-4/unit-01/overview"},"next":{"text":"第四册：流利英语 · 单元 1 单词与短语","link":"/life/english/new-concept/book-4/unit-01/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/grammar.md","filePath":"life/english/new-concept/book-4/unit-01/grammar.md"}'),s={name:"life/english/new-concept/book-4/unit-01/grammar.md"};function r(i,e,l,h,p,u){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="第四册-流利英语-·-单元-1-语法总结" tabindex="-1">第四册：流利英语 · 单元 1 语法总结 <a class="header-anchor" href="#第四册-流利英语-·-单元-1-语法总结" aria-label="Permalink to &quot;第四册：流利英语 · 单元 1 语法总结&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元复习与自测</a></p><h2 id="推测情态动词与过去事件" tabindex="-1">推测情态动词与过去事件 <a class="header-anchor" href="#推测情态动词与过去事件" aria-label="Permalink to &quot;推测情态动词与过去事件&quot;">​</a></h2><p>must have done 表示依据现有证据对过去作出较强推断，might have done 表示一种可能性，cannot have done 表示认为过去不可能如此。它们都不是对过去事实的直接报告。说明化石年代时，应先给观察再给推论；证据不足就不宜使用 must。must have left 不等于 had to leave，前者是推断离开过，后者是过去不得不离开。</p><p><strong>L1 原创例句：</strong> The marks might have been made by tools, but their origin remains uncertain.</p><p>这些痕迹可能是工具留下的，但其来源仍不确定。</p><p><strong>易错：</strong> 不要把 might have been made 译成“必定是造成的”；might 保留了其他解释。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-001">Lesson 1</a></p><h2 id="数量词与可数性" tabindex="-1">数量词与可数性 <a class="header-anchor" href="#数量词与可数性" aria-label="Permalink to &quot;数量词与可数性&quot;">​</a></h2><p>fewer 修饰可数名词复数，less 通常修饰不可数名词；a number of 后面接复数谓语，the number of 则把数量视为整体，接单数谓语。insects 是可数名词，damage 通常不可数。生态比较还必须交代比较对象和时间范围；fewer insects 只说明数量较少，不自动证明差异由蜘蛛造成。相关观察与因果解释应分开表达。</p><p><strong>L2 原创例句：</strong> The number of insects was lower in the sheltered garden.</p><p>避风花园中的昆虫数量较少。</p><p><strong>易错：</strong> The number of insects were lower 错在主谓一致；但 A number of insects were found 中复数正确。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-002">Lesson 2</a></p><h2 id="used-to、would-与过去状态" tabindex="-1">used to、would 与过去状态 <a class="header-anchor" href="#used-to、would-与过去状态" aria-label="Permalink to &quot;used to、would 与过去状态&quot;">​</a></h2><p>used to 可以描述过去的习惯，也可以描述如今不再成立的状态；would 叙述过去反复发生的动作时，需要已建立的过去时间背景。描述过去住在哪里等静态情况，通常用 used to live，而不是单独用 would live。一次特定登山经历用一般过去时。否定形式 did not use to 中 use 不加 d，疑问句同样由 did 承担过去时标记。</p><p><strong>L3 原创例句：</strong> The village used to be quiet, but each summer guides would welcome new climbers.</p><p>村庄过去很安静，但每年夏天向导们都会迎接新的登山者。</p><p><strong>易错：</strong> 不要用 would be quiet 无背景地替代 used to be quiet；would 还可能被理解为条件结果。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-003">Lesson 3</a></p><h2 id="报告动词与认知距离" tabindex="-1">报告动词与认知距离 <a class="header-anchor" href="#报告动词与认知距离" aria-label="Permalink to &quot;报告动词与认知距离&quot;">​</a></h2><p>claim that 表示提出主张，不表示说话者认可主张；report that 表示报告内容，其可靠性仍需评估。be said to 和 be reported to 将信息归于他人，可接 to have done 表示更早发生的动作。写历史科学材料时，不能把 is claimed to 改写成 can 而保持相同证据强度。实验主张应区分来源、方法、结果和可重复性；语法上的被动结构本身不增加可信度。</p><p><strong>L4 原创例句：</strong> The participant was reported to have identified the colour, but the test did not rule out visual cues.</p><p>据报告参与者辨认出了颜色，但实验没有排除视觉线索。</p><p><strong>易错：</strong> “was reported to identify”不是“被证实能够辨认”；reported 与 proved 的证据含义不同。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-004">Lesson 4</a></p><h2 id="让步从句与主句重心" tabindex="-1">让步从句与主句重心 <a class="header-anchor" href="#让步从句与主句重心" aria-label="Permalink to &quot;让步从句与主句重心&quot;">​</a></h2><p>although 和 even though 引导让步从句，后面需要主语和谓语；despite 后接名词或动名词，不能直接接普通完整句。主句承载作者仍然坚持的判断，前面的让步不是取消主句。Although young people lack some experience, they can offer new ideas. 中承认经验不足，但重点是新想法。英语通常不在同一句使用 although 与 but 双重连接两个分句。</p><p><strong>L5 原创例句：</strong> Although Lena had little experience, the team took her proposal seriously.</p><p>虽然莉娜经验不多，团队仍认真考虑了她的提议。</p><p><strong>易错：</strong> Although she was young, but she led the discussion. 应去掉 but；despite her youth 则不需要主谓结构。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-005">Lesson 5</a></p><h2 id="not-so-much-a-as-b-的纠正性对比" tabindex="-1">not so much A as B 的纠正性对比 <a class="header-anchor" href="#not-so-much-a-as-b-的纠正性对比" aria-label="Permalink to &quot;not so much A as B 的纠正性对比&quot;">​</a></h2><p>not so much A as B 表示与其说是 A，不如说是 B，重点在 B，不等于 A 和 B 一样多。A 与 B 最好保持语法平行，可以都是名词、动名词或形容词短语。The dispute was not so much about rules as about pride. 中两个 about 短语相互对应。此结构通常降低 A 的解释权重，并不一定完全否定 A；翻译时不能机械处理成数量比较。</p><p><strong>L6 原创例句：</strong> The argument was not so much about the score as about respect.</p><p>这场争论与其说是关于比分，不如说是关于尊重。</p><p><strong>易错：</strong> 不要将 not so much A as B 理解成“不如 A 那么 B”；它在两个解释之间强调后者。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-006">Lesson 6</a></p><h2 id="关系从句中的指代与功能说明" tabindex="-1">关系从句中的指代与功能说明 <a class="header-anchor" href="#关系从句中的指代与功能说明" aria-label="Permalink to &quot;关系从句中的指代与功能说明&quot;">​</a></h2><p>which 可以指物，who 指人；限制性关系从句帮助确定是哪一个对象，非限制性关系从句用逗号补充信息。The echoes that return first provide one clue. 中 that return first 限定 echoes。关系代词作主语时不能省略；作宾语时在限制性从句中通常可省。写机制说明时要让 which 紧靠明确先行词，避免读者不知它指声音、动物还是整个过程。</p><p><strong>L7 原创例句：</strong> The device measures the delay between a signal and the echo that returns from the wall.</p><p>这个装置测量信号与墙壁返回的回声之间的时间差。</p><p><strong>易错：</strong> 不能把 the echo that returns 写成 the echo returns 后仍接在原宾语位置；省略主语关系词会破坏结构。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-007">Lesson 7</a></p><h2 id="情态动词的被动结构" tabindex="-1">情态动词的被动结构 <a class="header-anchor" href="#情态动词的被动结构" aria-label="Permalink to &quot;情态动词的被动结构&quot;">​</a></h2><p>must be tested 表示必须被检测，should be tested 通常表示建议或较弱义务，may be tested 表示许可或可能；具体含义取决于语境。结构为情态动词 + be + 过去分词，不能省略 be。标准文件常用被动突出对象，但应在必要时加 by 短语说明责任人。课堂中的 must 只是练习设定的要求，不能据此推断现实法律规定。</p><p><strong>L8 原创例句：</strong> Under our workshop rules, every sample must be checked before it is packed.</p><p>按照我们工作坊的规定，每个样品都必须在包装前接受检查。</p><p><strong>易错：</strong> every sample must checked 缺少 be；必须写 must be checked。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-008">Lesson 8</a></p>',50)])])}const g=t(s,[["render",r]]);export{d as __pageData,g as default};
